actions.script:
if (ec.web.request.method!='POST') { ec.web.sendJsonError(405,'Use POST to load products.',null);return }
def p=ec.web.parameters
def access=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameter('sessionId',p.sessionId).call()
if (!access?.allowed || !p.sessionId) {
    ec.web.sendJsonError(403,'Select an authorized POS session.',null);return
}
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',p.sessionId)
    .condition('organizationPartyId',access.organizationPartyId).one()
if (session?.statusId!='PsOpen') {
    ec.web.sendJsonError(409,'This POS session is closed.',null);return
}
def modes=ec.service.sync().name('zenith.pos.PosModeServices.get#TerminalModes')
    .parameter('terminalId',session.terminalId).call().modes ?: []
def mode=p.salesModeId ? modes.find { it.salesModeId==p.salesModeId } : (modes.find { it.isDefault=='Y' } ?: modes.find())
if (!mode) { ec.web.sendJsonError(400,'Choose an available sales mode.',null);return }
def page=ec.service.sync().name('zenith.pos.PosCheckoutServices.get#PosCatalogPage')
    .parameters([sessionId:p.sessionId,searchTerm:p.searchTerm,catId:p.catId,productOffset:p.productOffset]).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:ec.message.errorsString]);return }
def prices=[:]
if (mode.priceSource=='PpsFixedProduct' && page.gridProducts) {
    ec.entity.find('zenith.erp.pos.PosProductModePrice').condition('organizationPartyId',access.organizationPartyId)
        .condition('salesModeId',mode.salesModeId).condition('productId','in',page.gridProducts*.productId).list()
        .each { prices[it.productId]=it.price }
}
def cards=page.gridProducts.collect { product ->
    def price=mode.priceSource=='PpsFixedProduct' ? prices[product.productId] : product.mrpAmount
    def blocked=mode.priceSource=='PpsFixedProduct' && price==null
    def stock=page.gridCardStock[product.productId] ?: [:]
    [productId:product.productId,name:product.productName ?: product.pseudoId ?: '',price:price ?: 0,blocked:blocked,
        priceText:blocked ? 'No '+mode.modeName+' price' : '₹'+ec.l10n.format(price ?: 0,'#,##0.##'),
        stockText:!stock.tracked ? 'Stock: not tracked' : stock.quantity!=null ? 'Stock: '+ec.l10n.format(stock.quantity,'#,##0.###') : 'Stock: unavailable']
}
ec.web.sendJsonResponse([success:true,products:cards,hasMore:page.gridHasMore,nextOffset:page.gridNextOffset])

// Fast path: when the JS billing client asks for JSON, return the print-receipt
// data straight from the payment response (no separate receiptData round-trip).
if (ec.web.requestParameters.wantJson) {
    if (ec.message.hasError()) {
        def _em = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonResponse([success:false, error:_em])
    } else {
        def _rcpt = null
        try {
            def _r = ec.service.sync().name("zenith.pos.PosServices.get#PosReceiptData").parameter("transactionId", transactionId).call()
            _rcpt = _r?.receipt
        } catch (Throwable _t) { /* receipt build must never fail an already-completed sale */ }
        if (_rcpt && _rcpt.success) {
            ec.web.sendJsonResponse(_rcpt)
        } else {
            // Sale DID complete; we just could not build the receipt here. Report success
            // (so the client never retries/double-charges) and let it fetch the receipt the normal way.
            ec.web.sendJsonResponse([success:true, receiptUnavailable:true, transactionId:transactionId])
        }
    }
}

// Restore the recalled bill, not the newer bill's mode from the submitting page.
def recalled = rOut?.transactionId ? ec.entity.find('zenith.erp.pos.PosTransaction')
    .condition('transactionId',rOut.transactionId).one() : null
if (recalled) {
    salesModeId = recalled.salesModeId
    taxOn = ((recalled.totalTaxAmount ?: 0) > 0) ? 'Y' : 'N'
}

def foundProduct = null



if (cartSearch) {



    foundProduct = ec.entity.find("mantle.product.Product")



        .condition("pseudoId", cartSearch).one()



    if (!foundProduct) {



        foundProduct = ec.entity.find("mantle.product.Product")



            .condition("productId", cartSearch).one()



    }



    if (!foundProduct) {



        def cond = ec.entity.conditionFactory.makeCondition("productName",



            org.moqui.entity.EntityCondition.ComparisonOperator.LIKE, "%" + cartSearch + "%")



        foundProduct = ec.entity.find("mantle.product.Product")



            .condition("productTypeEnumId", "PtAsset").condition(cond)



            .limit(1).one()



    }



}

else.script:
// State Code is the editable GST setting; regionGeoId may be an older
// non-GST Geo ID. Repair only that inherited value on an open cart.
def configuredOrigin = term2?.stateCode ?: term2?.regionGeoId ?: (_toggleGstConfig ? _toggleGstConfig[0].stateCode : null)
def storedOrigin = txn2.originRegionGeoId
def origin = storedOrigin ?: configuredOrigin
def validOrigin = origin ? ec.entity.find('zenith.erp.india.IndiaState').condition('stateCode', origin).one() : null
def inheritedLegacyOrigin = storedOrigin && storedOrigin == term2?.regionGeoId && !validOrigin
if (inheritedLegacyOrigin) {
    origin = configuredOrigin
    validOrigin = origin ? ec.entity.find('zenith.erp.india.IndiaState').condition('stateCode', origin).one() : null
}
def gstinState = txn2.customerTaxRegNumber && txn2.customerTaxRegNumber ==~ /[0-9]{2}[A-Z0-9]{13}/ ? txn2.customerTaxRegNumber.substring(0, 2) : null
def destination = txn2.destinationRegionGeoId ?: gstinState ?: origin
if (inheritedLegacyOrigin && txn2.destinationRegionGeoId == storedOrigin) destination = gstinState ?: origin
def validDestination = destination ? ec.entity.find('zenith.erp.india.IndiaState').condition('stateCode', destination).one() : null
taxStatesValid = validOrigin != null && validDestination != null
if (taxStatesValid) {
    if (txn2.originRegionGeoId != origin || txn2.destinationRegionGeoId != destination) {
        txn2.originRegionGeoId = origin
        txn2.destinationRegionGeoId = destination
        txn2.update()
    }
    taxOrigin = origin
    taxDestination = destination
} else {
    modeSwitchError = 'Set a valid POS terminal and customer supply state before enabling GST.'
    taxOn = 'N'
}

actions.script:
// Fast path: when the JS billing client asks for JSON, return the print-receipt
// data straight from the payment response (no separate receiptData round-trip).
if (ec.web.requestParameters.wantJson) {
    if (ec.message.hasError()) {
        def _em = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonResponse([success:false, error:_em])
    } else {
        def _rcpt = null
        try {
            def _r = ec.service.sync().name("zenith.pos.PosServices.get#PosReceiptData").parameter("transactionId", transactionId).call()
            _rcpt = _r?.receipt
        } catch (Throwable _t) { /* receipt build must never fail an already-completed sale */ }
        if (_rcpt && _rcpt.success) {
            ec.web.sendJsonResponse(_rcpt)
        } else {
            // Sale DID complete; we just could not build the receipt here. Report success
            // (so the client never retries/double-charges) and let it fetch the receipt the normal way.
            ec.web.sendJsonResponse([success:true, receiptUnavailable:true, transactionId:transactionId])
        }
    }
}

def results = []



if (term) {
    def posOrg = ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId
    // Match in SQL before limiting suggestions, so catalogue order cannot hide a valid code.
    def products=[]
    if(posOrg){
        def cf=ec.entity.conditionFactory;def EC=org.moqui.entity.EntityCondition
        def like='%'+term.toString().trim().replace('\\','\\\\').replace('%','\\%').replace('_','\\_')+'%'
        def codes=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:term.toString().trim()]).call().aliases
        def aliases=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',posOrg).condition('isActive','Y')
            .condition(cf.makeCondition([cf.makeCondition('barcodeValue',EC.LIKE,like).ignoreCase(),cf.makeCondition('barcodeValue',EC.IN,codes)],EC.OR)).list().collect{it.productId}
        def parts=['productName','pseudoId','productId'].collect{cf.makeCondition(it,EC.LIKE,like).ignoreCase()}
        if(aliases)parts.add(cf.makeCondition('productId',EC.IN,aliases))
        products=ec.entity.find('mantle.product.Product').condition('ownerPartyId',posOrg).condition('productTypeEnumId','PtAsset')
            .condition(cf.makeCondition(parts,EC.OR)).orderBy('productName').limit(10).list()
    }
    products.each { p ->



        results.add([productId: p.productId, pseudoId: p.pseudoId ?: '',



                     productName: p.productName ?: p.pseudoId ?: p.productId,



                     mrpAmount: p.mrpAmount ?: 0])



    }



}



ec.web.sendJsonResponse(results)

def term = (ec.web.parameters.term ?: '').toString().trim()
def termL = term.toLowerCase()
// Scope to the terminal's organization (like the product grid), falling back to the
// user's active org — so it also works for an admin driving a tenant's session.
def sessId = ec.web.parameters.sessionId
def orgId = null
if (sessId) { def s = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessId).one()
    if (s?.terminalId) orgId = ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", s.terminalId).one()?.organizationPartyId }
if (!orgId || orgId == '_NA_') { def ao = ec.user.getPreference('ACTIVE_ORGANIZATION'); orgId = (ao && ao != '_NA_') ? ao : null }
def out = []
try {
    def rows = ec.entity.find("mantle.party.PartyDetailAndRole")
        .condition("roleTypeId", "in", ['Customer','CustomerBillTo'])
        .condition("ownerPartyId", orgId)
        .orderBy("organizationName,firstName,lastName").limit(1000).list()
    def nameOf = { r -> (r.organizationName ?: (((r.firstName ?: '') + ' ' + (r.lastName ?: '')).trim())) ?: r.partyId }
    def custIdList = rows.collect { it.partyId }.unique()
    // Build partyId -> phone for the org's customers in a few bounded queries (no N+1).
    // Phones live in TelecomNumber (countryCode/areaCode/contactNumber), reached via PartyContactMech.
    def pid2phone = [:]
    if (custIdList) {
        def pcms = ec.entity.find("mantle.party.contact.PartyContactMech").condition("partyId", "in", custIdList)
            .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).list()
        def cmIds = pcms.collect { it.contactMechId }.unique()
        def cm2num = [:]
        if (cmIds) {
            ec.entity.find("mantle.party.contact.TelecomNumber").condition("contactMechId", "in", cmIds).list().each { tn ->
                cm2num[tn.contactMechId] = ((tn.countryCode ? ('+' + tn.countryCode + ' ') : '') + (tn.areaCode ?: '') + ' ' + (tn.contactNumber ?: '')).replaceAll("\\s+", " ").trim()
            }
        }
        pcms.each { pcm -> def n = cm2num[pcm.contactMechId]; if (n && !pid2phone[pcm.partyId]) pid2phone[pcm.partyId] = n }
    }
    def digits = term.replaceAll("[^0-9]", "")
    def seen = [:] as Map
    for (r in rows) {
        if (seen[r.partyId]) continue
        def nm = nameOf(r)
        def phone = pid2phone[r.partyId] ?: ''
        def phoneDigits = phone.replaceAll("[^0-9]", "")
        def match = !term || nm.toLowerCase().contains(termL) || (r.partyId ?: '').toLowerCase().contains(termL) || (digits.length() >= 3 && phoneDigits.contains(digits))
        if (!match) continue
        seen[r.partyId] = true
        out.add([partyId:r.partyId, name:nm, phone:phone, creditDays:ec.entity.find('mantle.party.Party').condition('partyId',r.partyId).one()?.creditDays])
        if (out.size() >= 30) break
    }
    ec.web.sendJsonResponse([success:true, customers:out])
} catch (Exception e) { ec.web.sendJsonResponse([success:false, error:e.message, customers:[]]) }

def txId = ec.web.parameters.transactionId
def cpid = ec.web.parameters.customerPartyId
def sid = ec.web.parameters.sessionId
if (!cpid || (!txId && !sid)) { ec.web.sendJsonResponse([success:false, error:'Missing customer or session']); return }
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameters([transactionId:txId,sessionId:sid,customerPartyId:cpid]).call()
if (!access?.allowed) { ec.web.sendJsonResponse([success:false,error:'Customer or bill unavailable in this organization.']); return }
// Selecting before the first item creates/reuses an unnumbered empty cart.
// The session lock in create#PosTransaction serializes concurrent first-item requests.
if (!txId) {
    def created = ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction').parameter('sessionId',sid).call()
    txId = created?.transactionId
    if (!txId || ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Could not prepare the empty bill.']); return }
}
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',txId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false,error:'This bill is already finalized']); return }
def registration = ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',cpid).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Customer tax registration is unavailable.']); return }
def destination = registration?.regionGeoId ?: txn.originRegionGeoId
def currentDestination = txn.destinationRegionGeoId ?: txn.originRegionGeoId
boolean hasContents = txn.transactionNumber || ((txn.paidAmount ?: 0) > 0) ||
    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).count() > 0 ||
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',txId).count() > 0
if (destination != currentDestination && hasContents) {
    ec.web.sendJsonResponse([success:false,error:'Choose a different tax destination before adding items or taking payment. Start a new bill to change it.']); return
}
def details = ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',cpid).limit(1).list()
def person = details ? details[0] : null
def name = person?.organizationName ?: (((person?.firstName ?: '')+' '+(person?.lastName ?: '')).trim()) ?: cpid
def phone = null
def mechanisms = ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId',cpid)
    .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()
for (mechanism in mechanisms) {
    def number = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId',mechanism.contactMechId).one()
    if (number) { phone = ((number.countryCode ? ('+'+number.countryCode+' ') : '')+(number.areaCode ?: '')+' '+(number.contactNumber ?: '')).replaceAll('\\s+',' ').trim(); if (phone) break }
}
def gstin = registration?.registrationNumber
ec.service.sync().name('update#zenith.erp.pos.PosTransaction').parameters([
    transactionId:txId,customerPartyId:cpid,customerName:name,customerPhone:phone,
    customerTaxRegNumber:gstin,destinationRegionGeoId:destination]).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Customer could not be changed.']); return }
ec.web.sendJsonResponse([success:true,transactionId:txId,customer:name,customerPhone:phone ?: '',customerPartyId:cpid,customerGstin:gstin ?: ''])

def txId = ec.web.parameters.transactionId
if (!txId) { ec.web.sendJsonResponse([success:false,error:'Missing bill']); return }
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',txId).call()
if (!access?.allowed) { ec.web.sendJsonResponse([success:false,error:'Bill unavailable in this organization.']); return }
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',txId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false,error:'This bill is already finalized']); return }
boolean hasContents = txn.transactionNumber || ((txn.paidAmount ?: 0) > 0) ||
    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).count() > 0 ||
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',txId).count() > 0
if ((txn.destinationRegionGeoId ?: txn.originRegionGeoId) != txn.originRegionGeoId && hasContents) {
    ec.web.sendJsonResponse([success:false,error:'Start a new bill to clear a customer with a different tax destination. Existing bill amounts are preserved.']); return
}
txn.customerPartyId = null; txn.customerName = null; txn.customerPhone = null
txn.customerTaxRegNumber = null; txn.destinationRegionGeoId = txn.originRegionGeoId; txn.update()
ec.web.sendJsonResponse([success:true,customer:'',customerPhone:'',customerPartyId:''])

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
if (!access?.allowed || ec.web.parameters.organizationPartyId != access.organizationPartyId) {
    throw new org.moqui.context.ArtifactAuthorizationException('Select the authorized organization before recovering offline sales.')
}
def candidates
try { candidates = new groovy.json.JsonSlurper().parseText(ec.web.parameters.candidates ?: '[]') }
catch (Exception ignored) { ec.web.response.setStatus(400); ec.web.sendJsonResponse([eligibleIds:[]]); return }
if (!(candidates instanceof List) || candidates.size() > 200) {
    ec.web.response.setStatus(400); ec.web.sendJsonResponse([eligibleIds:[]]); return
}
def eligible = []
for (candidate in candidates) {
    if (!(candidate instanceof Map) || !(candidate.offlineId instanceof String) || !candidate.offlineId || candidate.offlineId.length() > 255 ||
        !(candidate.sessionId instanceof String) || !(candidate.terminalId instanceof String)) continue
    if (candidate.organizationPartyId && candidate.organizationPartyId != access.organizationPartyId) continue
    def session = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',candidate.sessionId)
        .condition('organizationPartyId',access.organizationPartyId).one()
    def terminal = ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',candidate.terminalId)
        .condition('organizationPartyId',access.organizationPartyId).one()
    // one() may resolve by primary key; compare stored ownership explicitly.
    if (session?.organizationPartyId == access.organizationPartyId && terminal?.organizationPartyId == access.organizationPartyId &&
        session.terminalId == terminal.terminalId) eligible.add(candidate.offlineId)
}
ec.web.sendJsonResponse([organizationPartyId:access.organizationPartyId,eligibleIds:eligible.unique()])

try {
    ec.service.sync().name('zenith.pos.PosServices.close#PosSession')
        .parameters([sessionId:sessionId,closingCash:closingCash]).call()
} catch (Exception failure) {
    ec.transaction.setRollbackOnly('POS session close failed',failure)
    if (!ec.message.hasError()) ec.message.addError('Session could not be closed. No changes were saved.')
}
def returnUrl = ec.web.getWebappRootUrl(true, null) + '/apps/zenith/pos/Terminal?sessionId=' + java.net.URLEncoder.encode((sessionId ?: '').toString(), 'UTF-8')
if (ec.web.requestParameters.wantJson == '1') {
    ec.web.sendJsonResponse([success:!ec.message.hasError(), error:ec.message.hasError() ? ec.message.errorsString : null,
        redirectUrl:ec.message.hasError() ? null : returnUrl])
} else if (!ec.message.hasError()) {
    ec.web.response.sendRedirect(returnUrl)
}

def state = ec.service.sync().name('zenith.pos.PosFreeItemServices.get#FreeItemApprovalState').parameters([transactionId:transactionId]).call()
def manager = ec.service.sync().name('zenith.pos.PosFreeItemServices.get#ManagerApprovalAccess').call()
ec.web.sendJsonResponse([success:!ec.message.hasError(),required:state?.required,freeItemCount:state?.freeItemCount,freeItems:state?.freeItems,approvalFingerprint:state?.approvalFingerprint,canApprove:manager?.canApprove,error:ec.message.errorsString])

try {
    def approval = ec.service.sync().name('zenith.pos.PosFreeItemServices.approve#FreeItems')
        .parameters([transactionId:transactionId,reason:ec.web.parameters.reason,managerPin:ec.web.parameters.managerPin,expectedFingerprint:ec.web.parameters.expectedFingerprint]).call()
    ec.web.sendJsonResponse([success:!ec.message.hasError(),approvalId:approval?.approvalId,error:ec.message.errorsString])
} catch (Exception ignored) {
    def message = ec.message.errorsString ?: 'Free items could not be approved.'
    ec.message.clearErrors();ec.web.sendJsonResponse([success:false,error:message])
}

def p = ec.web.parameters



def action = p.action



def sessionId = p.sessionId



def transactionId = p.transactionId



def taxOn = p.taxOn ?: 'N'



def result = [success:false]



try {



    if (transactionId && ['addItem','setItemMode','updateQty','updatePrice','applyDiscount','removeItem','clearCart','scanAdd','refresh'].contains(action)) {
        def editable=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
        if (!editable || editable.statusId!='PtCreated') { ec.web.sendJsonResponse([success:false,cartClosed:true,transactionId:'',error:'That bill is already issued or no longer open. Starting a fresh cart; use History to amend an issued bill.']);return }
    }
    if (action == 'cardStock') {
        def ids=(p.productIds ?: '').toString().split(',').take(120).toList()
        def stockResult=ec.service.sync().name('zenith.pos.PosCheckoutServices.get#PosCardStock').parameters([sessionId:sessionId,productIds:ids]).call()
        if (ec.message.hasError()) { def error=ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false,error:error]);return }
        ec.web.sendJsonResponse([success:true,stock:stockResult.stock ?: [:]]);return
    } else if (action == 'clearCart') {
        ec.service.sync().name('zenith.pos.PosCheckoutServices.clear#PosDraftCart').parameters([sessionId:sessionId,transactionId:transactionId]).call()
        if (ec.message.hasError()) { def error=ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false,error:error]);return }
    } else if (action == 'addItem') {



        def productId = p.productId



        def unitPrice = p.unitPrice && (p.unitPrice as BigDecimal) != BigDecimal.ZERO ? (p.unitPrice as BigDecimal) : BigDecimal.ZERO


        if (unitPrice == BigDecimal.ZERO && productId) {


            def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()


            if (prod?.mrpAmount) unitPrice = prod.mrpAmount as BigDecimal


            if (unitPrice == BigDecimal.ZERO) {


                def pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptList").orderBy("-lastUpdatedStamp").limit(1).one()


                if (!pp) pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptCurrent").orderBy("-lastUpdatedStamp").limit(1).one()


                if (pp?.price) unitPrice = pp.price as BigDecimal


            }


        }



        def addQty = p.addQty ? (p.addQty as BigDecimal) : BigDecimal.ONE



        if (!transactionId) {



            def tOut = ec.service.sync().name("zenith.pos.PosServices.create#PosTransaction")



                .parameters([sessionId:sessionId]).call()



            transactionId = tOut.transactionId



        }



        ec.service.sync().name("zenith.pos.PosServices.add#PosTransactionItem")



            .parameters([transactionId:transactionId, productId:productId,



                quantity:addQty, unitPrice:unitPrice, discountPercent:(p.salesModeId ? (ec.entity.find("zenith.erp.pos.PosSalesMode").condition("salesModeId", p.salesModeId).one()?.discountPercent ?: 0) : 0), salesModeId:p.salesModeId, taxOn:taxOn]).call()

        // Explicit per-mode pricing may block the add (no price set) -> surface it so the client rolls back.
        if (ec.message.hasError()) { def _em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:_em, transactionId:transactionId]); return }

        if (taxOn == 'N') {



            def lastItems = ec.entity.find("zenith.erp.pos.PosTransactionItem")



                .condition("transactionId", transactionId).orderBy("-itemSeqId").list()



            if (lastItems) {



                def la = lastItems[0]



                ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                    .parameters([transactionId:transactionId, itemSeqId:la.itemSeqId,



                        totalTaxAmount:0, lineTotal:la.taxableAmount]).call()



                ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                    .parameters([transactionId:transactionId]).call()



            }



        }



    } else if (action == 'setItemMode') {
        ec.service.sync().name("zenith.pos.PosServices.set#PosTransactionItemMode")
            .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, salesModeId:p.itemMode, taxOn:p.taxOn]).call()
        if (ec.message.hasError()) { def _em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:_em, transactionId:transactionId]); return }
        // An explicit per-line mode choice takes manual control: don't let quantity-break auto-override it.
        ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
            .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, manualPrice:'Y']).call()
    } else if (action == 'updateQty') {



        def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")



            .condition("transactionId", transactionId).condition("itemSeqId", p.itemSeqId).one()



        if (item) {



            def nq = null
            try { nq = new BigDecimal((p.newQty ?: '').toString()) } catch (Exception ignored) {}
            if (nq==null || nq<=0) { ec.web.sendJsonResponse([success:false,error:'Quantity must be greater than zero. Use Remove to delete a line.']);return }
            ec.service.sync().name('zenith.pos.PosStockServices.check#PosCartStock').parameters([
                transactionId:transactionId, productId:item.productId, quantityDelta:nq - ((item.quantity ?: 0) as BigDecimal)]).call()
            if (ec.message.hasError()) { def error=ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false,error:error]); return }




            if (nq <= 0) {



                ec.service.sync().name("zenith.pos.PosServices.remove#PosTransactionItem")



                    .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId]).call()



            } else {



                def ls = nq * (item.unitPrice as BigDecimal)



                def da = ls * ((item.discountPercent ?: 0) as BigDecimal) / 100



                def ta = ls - da



                def taxR = BigDecimal.ZERO



                if (taxOn != 'N' && item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {



                    taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)



                }



                def tt = ta * taxR



                def lt = ta + tt



                ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                    .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId,



                        quantity:nq, discountAmount:da, taxableAmount:ta,



                        totalTaxAmount:tt, lineTotal:lt]).call()



            }



            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                .parameters([transactionId:transactionId]).call()

            // Quantity-break: re-evaluate this line's retail/wholesale mode for the new quantity.
            ec.service.sync().name("zenith.pos.PosServices.applyQuantityBreak#Line")
                .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, taxOn:taxOn, cartModeId:salesModeId]).call()

        }



    } else if (action == 'updatePrice') {
        ec.service.sync().name('zenith.pos.PosPriceServices.set#ItemPrice').parameters([
            transactionId:transactionId,itemSeqId:p.itemSeqId,newPrice:p.newPrice,taxOn:taxOn]).call()
        if (ec.message.hasError()) {
            def error = ec.message.errorsString
            ec.message.clearErrors(); ec.web.sendJsonResponse([success:false,error:error]); return
        }
    } else if (action == 'applyDiscount') {
        def dTxId = transactionId ?: p.transactionId
        def dTxn = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", dTxId).one()
        if (!dTxn || dTxn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false, error:'No open bill to discount']); return }
        def dItems = ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", dTxId).orderBy("itemSeqId").list()
        if (!dItems) { ec.web.sendJsonResponse([success:false, error:'Add items before applying a discount']); return }
        def dTermId = null
        def dSess = sessionId ? ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one() : null
        if (dSess) dTermId = dSess.terminalId
        def dTerm = dTermId ? ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", dTermId).one() : null
        // Discount config is stored per-organization as UserPreference key/values
        // (POS_DISC_LIMIT / POS_DISC_PIN / POS_DISC_ROUNDSTEP), set from the POS settings.
        def dOrg = dTerm?.organizationPartyId
        def dCfg = { k -> dOrg ? ec.entity.find("moqui.security.UserPreference").condition("userId", dOrg).condition("preferenceKey", k).one()?.preferenceValue : null }
        def _lim = dCfg('POS_DISC_LIMIT'); def dLimit = (_lim != null && _lim.toString().trim() != '') ? new BigDecimal(_lim.toString().trim()) : null
        def dPin = dCfg('POS_DISC_PIN')
        def _step = dCfg('POS_DISC_ROUNDSTEP'); def dStep = (_step != null && _step.toString().trim() != '') ? new BigDecimal(_step.toString().trim()) : BigDecimal.ZERO
        def lineMap = [:]
        if (p.lineDiscounts) { try { lineMap = new groovy.json.JsonSlurper().parseText(p.lineDiscounts) } catch (Exception _e) { lineMap = [:] } }
        // intended per-line discount amounts
        def grossTotal = BigDecimal.ZERO
        def lineCalc = [:]
        dItems.each { itm ->
            def sub = ((itm.quantity ?: 0) as BigDecimal) * ((itm.unitPrice ?: 0) as BigDecimal)
            grossTotal += sub
            def dAmt = BigDecimal.ZERO
            def ld = lineMap[itm.itemSeqId]
            if (ld) { def v = ((ld.v ?: 0) as BigDecimal); dAmt = (ld.t == 'amt') ? v : (sub * v / 100) }
            if (dAmt < 0) dAmt = BigDecimal.ZERO
            if (dAmt > sub) dAmt = sub
            lineCalc[itm.itemSeqId] = [sub:sub, disc:dAmt]
        }
        // whole-bill discount, apportioned across lines on their after-line-discount base
        def afterLine = grossTotal - (lineCalc.values().sum { it.disc } ?: BigDecimal.ZERO)
        def billVal = (p.billDiscValue ?: 0) as BigDecimal
        if (billVal > 0 && afterLine > 0) {
            def billDisc = (p.billDiscType == 'amt') ? billVal : (afterLine * billVal / 100)
            if (billDisc > afterLine) billDisc = afterLine
            dItems.each { itm -> def lc = lineCalc[itm.itemSeqId]; def base = lc.sub - lc.disc
                lc.disc = lc.disc + (afterLine != 0 ? (billDisc * base / afterLine) : BigDecimal.ZERO)
                if (lc.disc > lc.sub) lc.disc = lc.sub }
        }
        // manager-PIN gate on the effective overall discount %
        def totalDisc = lineCalc.values().sum { it.disc } ?: BigDecimal.ZERO
        def effPct = grossTotal > 0 ? (totalDisc * 100 / grossTotal) : BigDecimal.ZERO
        if (dLimit != null && effPct > dLimit) {
            if (!dPin || (p.managerPin ?: '') != dPin) {
                ec.web.sendJsonResponse([success:false, needPin:true, error:'Manager PIN required for a discount above ' + dLimit + '%'])
                return
            }
        }
        // Persist discounts, then use the shared calculator for both line totals
        // and GST details. Scaling a saved tax ratio leaves stale breakdown rows
        // and treats tax-inclusive prices as exclusive.
        dItems.each { itm ->
            def lc = lineCalc[itm.itemSeqId]; def sub = lc.sub; def dAmt = lc.disc
            def dPct = sub > 0 ? (dAmt * 100 / sub) : BigDecimal.ZERO
            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:dTxId, itemSeqId:itm.itemSeqId,
                    discountPercent:dPct, discountAmount:dAmt]).call()
        }
        ec.service.sync().name('zenith.pos.PosServices.refresh#PosTransactionTax')
            .parameters([transactionId:dTxId,taxOn:taxOn]).call()
        if (ec.message.hasError()) throw new IllegalArgumentException(ec.message.errorsString)
        // reduction: round the payable DOWN to the nearest configured step
        if ((p.roundOff ?: '') == 'Y' && dStep > 0) {
            def dT2 = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", dTxId).one()
            def grand = (dT2.grandTotal ?: 0) as BigDecimal
            def payable = (grand / dStep).setScale(0, java.math.RoundingMode.FLOOR) * dStep
            ec.service.sync().name("update#zenith.erp.pos.PosTransaction")
                .parameters([transactionId:dTxId, payableAmount:payable, roundOff:(payable - grand)]).call()
        }
        def dF = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", dTxId).one()
        ec.web.sendJsonResponse([success:true, subtotal:dF.subtotal, tax:dF.totalTaxAmount, discount:dF.discountTotal, grand:dF.grandTotal, roundOff:dF.roundOff, payable:dF.payableAmount])
        return
    } else if (action == 'removeItem') {



        ec.service.sync().name("zenith.pos.PosServices.remove#PosTransactionItem")



            .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId]).call()



        ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



            .parameters([transactionId:transactionId]).call()



    } else if (action == 'scanAdd') {



        def code = p.cartSearch



        def foundProduct = null
        def dupCode = false



        if (code) {



            def match=ec.service.sync().name('zenith.barcode.BarcodeServices.resolve#ScanProduct').parameters([code:code]).call()
            dupCode=match?.ambiguous ?: false
            if(match?.found)foundProduct=ec.entity.find('mantle.product.Product').condition('productId',match.productId).one()
            // Partial text belongs to type-ahead selection; a scanner Enter never guesses a product.

        }



        if (foundProduct) {



            if (!transactionId) {



                def tOut = ec.service.sync().name("zenith.pos.PosServices.create#PosTransaction")



                    .parameters([sessionId:sessionId]).call()



                transactionId = tOut.transactionId



            }



            ec.service.sync().name("zenith.pos.PosServices.add#PosTransactionItem")



                .parameters([transactionId:transactionId, productId:foundProduct.productId,



                    quantity:1, discountPercent:0, salesModeId:p.salesModeId, taxOn:taxOn]).call()
            // Per-mode pricing may block an unpriced product in a fixed mode -> surface it so the client rolls back the scan.
            if (ec.message.hasError()) { def _em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:_em, transactionId:transactionId]); return }



            if (taxOn == 'N') {



                def lastItems = ec.entity.find("zenith.erp.pos.PosTransactionItem")



                    .condition("transactionId", transactionId).orderBy("-itemSeqId").list()



                if (lastItems) {



                    def la = lastItems[0]



                    ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                        .parameters([transactionId:transactionId, itemSeqId:la.itemSeqId,



                            totalTaxAmount:0, lineTotal:la.taxableAmount]).call()



                    ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                        .parameters([transactionId:transactionId]).call()



                }



            }



        } else {



            result = dupCode ? [success:false, error:'More than one product has the code "' + code + '". Fix the duplicate in Barcodes before scanning.'] : [success:false, error:'Product not found: ' + code]



            ec.web.sendJsonResponse(result)



            return



        }



    } else if (action == 'receiptData') {

        def rTxId = ec.web.requestParameters.transactionId ?: transactionId
        def _r = ec.service.sync().name("zenith.pos.PosServices.get#PosReceiptData").parameter("transactionId", rTxId).call()
        ec.web.sendJsonResponse(_r?.receipt ?: [success:false, error:'Transaction not found'])
        return
                        } else if (action == 'searchProductsJson') {
        def q = (p.q ?: '').toString().trim()
        def products = []
        if (q && q.length() >= 1) {
            // Match the entire authorized catalog before limiting suggestions.
            def cf = ec.entity.conditionFactory
            def EC = org.moqui.entity.EntityCondition
            def like = '%' + q.replace('\\','\\\\').replace('%','\\%').replace('_','\\_') + '%'
            def matches = ['productName','pseudoId','productId'].collect { cf.makeCondition(it,EC.LIKE,like).ignoreCase() }
            def prods = ec.entity.find('mantle.product.Product')
                .condition('ownerPartyId',posOrganizationPartyId ?: '__NO_ORGANIZATION__')
                .condition('productTypeEnumId','PtAsset').condition(cf.makeCondition(matches,EC.OR))
                .orderBy('productName,productId').limit(10).list()
            prods.each { pr ->
                def price = pr.mrpAmount ?: 0
                if (!price || price == 0) {
                    def pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", pr.productId).condition("priceTypeEnumId", "PptList").orderBy("-lastUpdatedStamp").limit(1).one()
                    if (!pp) pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", pr.productId).condition("priceTypeEnumId", "PptCurrent").orderBy("-lastUpdatedStamp").limit(1).one()
                    if (pp?.price) price = pp.price
                }
                products.add([pid:pr.productId, name:pr.productName ?: pr.productId, price:price ?: 0])
            }
        }
        result = [success:true, action:'searchProductsJson', products:products]
        ec.web.sendJsonResponse(result)
        return
    } else if (action == 'creditBills') {
        // List unpaid CREDIT bills across the operator's organization
        def histTermId = null
        if (sessionId) { def cs = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one(); histTermId = cs?.terminalId }
        if (!histTermId) { def rec = ec.entity.find("zenith.erp.pos.PosSession").condition("operatorPartyId", ec.user.userAccount?.partyId).orderBy("-openDate").limit(1).list(); if (rec) histTermId = rec[0].terminalId }
        def ct = histTermId ? ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", histTermId).one() : null
        def orgTerms = ct?.organizationPartyId ? (ec.entity.find("zenith.erp.pos.PosTerminal").condition("organizationPartyId", ct.organizationPartyId).list()*.terminalId) : (histTermId ? [histTermId] : null)
        def sessIds = orgTerms ? (ec.entity.find("zenith.erp.pos.PosSession").condition("terminalId", "in", orgTerms).list()*.sessionId) : null
        if (!sessIds) { ec.web.sendJsonResponse([success:true, action:'creditBills', bills:[], total:0]); return }
        def crTxns = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId",ct?.organizationPartyId ?: ec.user.getPreference('ACTIVE_ORGANIZATION') ?: '__NO_ORGANIZATION__').condition("sessionId", "in", sessIds).condition("isCredit", "Y").orderBy("-entryDate").list()
        def crSearch = (p.search ?: '').toLowerCase()
        // ---- all-time stats (across every credit bill, before the search filter) ----
        def _nowCr = ec.user.nowTimestamp
        def _cCr = java.util.Calendar.getInstance(); _cCr.setTime(_nowCr); _cCr.set(java.util.Calendar.DAY_OF_MONTH, 1); _cCr.set(java.util.Calendar.HOUR_OF_DAY,0); _cCr.set(java.util.Calendar.MINUTE,0); _cCr.set(java.util.Calendar.SECOND,0)
        def _crMonthStart = new java.sql.Timestamp(_cCr.getTimeInMillis())
        def creditState = { tx, due ->
            if(tx.statusId!='PtCompleted') return 'Cancelled'
            if(due<=0) return 'Settled'
            if(!tx.creditDueDate){def _t=_nowCr.toInstant().atZone(java.time.ZoneId.of(ec.user.timeZone.ID)).toLocalDate(); return (tx.entryDate && java.time.temporal.ChronoUnit.DAYS.between(tx.entryDate.toInstant().atZone(java.time.ZoneId.of(ec.user.timeZone.ID)).toLocalDate(), _t) > 30) ? 'Overdue' : 'Open'}
            def today=_nowCr.toInstant().atZone(java.time.ZoneId.of(tx.creditTimeZone ?: ec.user.timeZone.ID)).toLocalDate()
            def remaining=java.time.temporal.ChronoUnit.DAYS.between(today,tx.creditDueDate.toLocalDate())
            remaining<0?'Overdue':remaining<=2?'Due soon':'Open'
        }
        def crAllCount = crTxns.size(); def crOutCount = 0; def crOutSum = 0 as BigDecimal; def crOverdue = 0
        def creditTxnIds = crTxns.collect { it.transactionId }
        def creditPayments = creditTxnIds ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId','in',creditTxnIds).orderBy('paymentDate,paymentId').list().groupBy { it.transactionId } : [:]

        crTxns.each { tx -> def _o = ((tx.payableAmount ?: 0) as BigDecimal) - ((tx.paidAmount ?: 0) as BigDecimal); if (_o > 0) { crOutCount++; crOutSum += _o; if (creditState(tx,_o)=='Overdue') crOverdue++ } }
        def crPaidMonthAmt = 0 as BigDecimal; def crPaidMonthCount = 0
        if (creditTxnIds) {
            def _pm = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",creditTxnIds).condition("paymentDate","greater-equals",_crMonthStart).list()
            crPaidMonthAmt = _pm.sum { (it.amount ?: 0) as BigDecimal } ?: (0 as BigDecimal)
            crPaidMonthCount = _pm.collect { it.transactionId }.unique().size()
        }
        // ---- list (search-filtered) ----
        def crBills = []
        crTxns.each { tx ->
            if (crSearch && !((tx.transactionNumber ?: '').toLowerCase().contains(crSearch) || (tx.customerName ?: '').toLowerCase().contains(crSearch) || (tx.customerPhone ?: '').toLowerCase().contains(crSearch))) return
            def items = ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", tx.transactionId).list()
            def payable = (tx.payableAmount ?: 0) as BigDecimal
            def paid = (tx.paidAmount ?: 0) as BigDecimal
            def payments = creditPayments[tx.transactionId] ?: []
            def lastPayment = payments ? payments[-1].paymentDate : null
            def state = creditState(tx,payable-paid)
            crBills.add([dueDate:tx.creditDueDate?.toString(),creditStatus:state,
                lastPayment:lastPayment ? ec.l10n.format(lastPayment,'dd MMM yyyy, hh:mm a z') : null,
                settledOn:state=='Settled' && lastPayment ? ec.l10n.format(lastPayment,'dd MMM yyyy, hh:mm a z') : null,txId: tx.transactionId, billNo: tx.transactionNumber ?: tx.transactionId,
                date: ec.l10n.format(tx.entryDate, 'dd/MM/yyyy hh:mm a'), ts: (tx.entryDate ? tx.entryDate.getTime() : 0L),
                customer: tx.customerName ?: 'Walk-In', phone: tx.customerPhone ?: '',
                grand: payable, paid: paid, outstanding: payable - paid, itemCount: items.size()])
        }
        def crTotalOutstanding = 0 as BigDecimal
        crBills.each { crTotalOutstanding += (it.outstanding as BigDecimal) }
        ec.web.sendJsonResponse([success:true, action:'creditBills', bills:crBills, total:crBills.size(), totalOutstanding:crTotalOutstanding,
            allCount:crAllCount, outCount:crOutCount, outSum:crOutSum, overdueCount:crOverdue, paidMonthAmt:crPaidMonthAmt, paidMonthCount:crPaidMonthCount])
        return
    } else if (action == 'settleCredit') {
        def stxId = p.settleTxId
        def smethod = p.settleMethod
        def samt = p.settleAmount ? (p.settleAmount as BigDecimal) : BigDecimal.ZERO
        def sref = p.settleRef
        if (!stxId || !smethod || samt <= BigDecimal.ZERO) { ec.web.sendJsonResponse([success:false, error:'Missing settlement details']); return }
        try {
            def rOut = ec.service.sync().name("zenith.pos.PosServices.settle#PosCredit")
                .parameters([transactionId:stxId, paymentMethod:smethod, amount:samt, referenceNumber:sref, collectionSessionId:sessionId]).call()
            if (ec.message.hasError()) { def em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:em]); return }
            ec.web.sendJsonResponse([success:true, outstanding:rOut.outstanding, fullyPaid:rOut.fullyPaid, paidAmount:rOut.paidAmount])
        } catch (Exception se) {
            ec.web.sendJsonResponse([success:false, error:se.message])
        }
        return
    } else if (action == 'billHistory') {
        def search = p.search ?: ''
        def offset = p.offset ? (p.offset as int) : 0
        def limit = p.histLimit ? (p.histLimit as int) : 20
        // History belongs to the chosen terminal; owner dashboards aggregate shops separately.
        def histTermId = null
        if (sessionId) {
            def curSess = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one()
            histTermId = curSess?.terminalId
        }
        if (!histTermId && p.terminalId) histTermId = p.terminalId
        if (!histTermId) {
            def recentSess = ec.entity.find("zenith.erp.pos.PosSession").condition("organizationPartyId",posOrganizationPartyId).condition("operatorPartyId", ec.user.userAccount?.partyId).orderBy("-openDate").limit(1).list()
            if (recentSess) histTermId = recentSess[0].terminalId
        }
        def curTerm = histTermId ? ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", histTermId).condition('organizationPartyId',posOrganizationPartyId).one() : null
        if (!curTerm) { ec.web.sendJsonResponse([success:true, action:'billHistory', bills:[], total:0, offset:0]); return }
        def txnBase = ec.entity.find("zenith.erp.pos.PosTransactionView")
            .condition("organizationPartyId",posOrganizationPartyId).condition("terminalId",curTerm.terminalId).condition("statusId", "PtCompleted")
        if (!ec.user.isInGroup('ADMIN') && !ec.user.isInGroup('ZENITH_ADMIN') && !ec.user.isInGroup('ZENITH_STORE_MGR')) {
            txnBase.condition('operatorPartyId',ec.user.userAccount?.partyId)
        }
        BigDecimal searchAmt = null
        if (search) {
            try { searchAmt = new BigDecimal(search) } catch (Exception ignored) {}
            def _ecf = ec.entity.conditionFactory
            def _or = []
            _or.add(_ecf.makeCondition("transactionNumber", org.moqui.entity.EntityCondition.LIKE, "%" + search + "%"))
            _or.add(_ecf.makeCondition("customerName", org.moqui.entity.EntityCondition.LIKE, "%" + search + "%"))
            if (searchAmt != null) _or.add(_ecf.makeCondition("grandTotal", org.moqui.entity.EntityCondition.EQUALS, searchAmt))
            txnBase.condition(_ecf.makeCondition(_or, org.moqui.entity.EntityCondition.OR))
        }
        def totalCount = txnBase.count()
        def txns = txnBase.orderBy("-entryDate").offset(offset).limit(limit).list()
        def bills = []
        txns.each { tx ->
            def items = ec.entity.find("zenith.erp.pos.PosTransactionItem")
