            def amendments = ec.entity.find("zenith.erp.pos.PosTransactionAmendment")
                .condition("transactionId", tx.transactionId).orderBy("-amendmentDate").list()
            bills.add([txId: tx.transactionId, billNo: tx.transactionNumber ?: tx.transactionId,
                date: ec.l10n.format(tx.entryDate, 'dd/MM/yyyy hh:mm a'),
