                subtotal: tx.subtotal ?: 0, tax: tx.totalTaxAmount ?: 0,
                discount: tx.discountTotal ?: 0, grand: tx.grandTotal ?: 0,
                payable: tx.payableAmount ?: 0,
                itemCount: items.size(),
                items: items.collect { [seq: it.itemSeqId, pid: it.productId,
                    name: it.productName ?: it.productId, qty: it.quantity ?: 0,
                    price: it.unitPrice ?: 0, discount: it.discountAmount ?: 0,
                    tax: it.totalTaxAmount ?: 0, total: it.lineTotal ?: 0, mode:(it.salesModeId ? (ec.entity.find("zenith.erp.pos.PosSalesMode").condition("salesModeId", it.salesModeId).one()?.modeName ?: "") : ""), uom:(it.uomId ? (["OTH_ea":'Nos',"WT_g":'g',"WT_kg":'kg',"VLIQ_ml":'ml',"VLIQ_L":'L',"LEN_m":'m',"LEN_cm":'cm'].get(it.uomId) ?: '') : '')] },
                payments: payments.collect { [method: it.paymentMethod ?: '', amount: it.amount ?: 0] },
                amendCount: amendments.size(),
                amendments: amendments.collect { [date: ec.l10n.format(it.amendmentDate, 'dd/MM hh:mm a'),
                    type: it.changeType ?: '', reason: it.reason ?: '',
                    product: it.productName ?: '', oldVal: it.oldValue ?: '', newVal: it.newValue ?: ''] }
            ])
        }
        result = [success:true, action:'billHistory', bills:bills, total:totalCount, offset:offset]
        ec.web.sendJsonResponse(result)
        return
    } else if (action == 'amendBill') {
        def txId = p.editTxId
        def reason = (p.editReason ?: '').trim()
        if (!reason) { ec.web.sendJsonResponse([success:false, error:'Enter a reason before saving or printing an edited bill.']); return }
        if (reason.length() > 500) { ec.web.sendJsonResponse([success:false, error:'Keep the edit reason under 500 characters.']); return }
        def txn = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).forUpdate(true).one()
        if (!txn || txn.statusId != 'PtCompleted') {
            ec.web.sendJsonResponse([success:false, error:'Transaction not found or not editable'])
            return
        }
        // Validate the whole requested edit before writing. A single ajaxCart request
        // owns one DB transaction, so Save & Print cannot leave half a revised bill.
        def editOps
        try {
            editOps = p.editOps ? new groovy.json.JsonSlurper().parseText(p.editOps.toString()) :
                [[type:p.editType, seq:p.editItemSeqId, newQty:p.newQty, newPrice:p.newPrice,
                  productId:p.addProductId, addQty:p.addQty]]
        } catch (Exception ignored) { editOps = null }
        if (!(editOps instanceof List) || !editOps || editOps.size() > 50 || editOps.any { !(it instanceof Map) }) {
            ec.web.sendJsonResponse([success:false, error:'Choose 1 to 50 valid bill changes.']); return
        }
        def originalItems = ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId', txId).list()
        def originalSeqs = originalItems.collect { it.itemSeqId } as Set
        def billHasTax = originalItems.any { ((it.totalTaxAmount ?: 0) as BigDecimal) > 0 }
        int nextItemSeq = (originalItems.collect { it.itemSeqId as int }.max() ?: 0) as int
        def removedSeqs = [] as Set
        int addedCount = 0
        for (def op : editOps) {
            def type = op.type
            if (!['QTY_CHANGE','PRICE_CHANGE','ITEM_ADDED','ITEM_REMOVED'].contains(type)) {
                ec.web.sendJsonResponse([success:false, error:'Choose a valid amendment.']); return
            }
            if (type == 'ITEM_ADDED') {
                def prod = op.productId ? ec.entity.find('mantle.product.Product').condition('productId', op.productId).one() : null
                if (!prod || prod.ownerPartyId != txn.organizationPartyId) {
                    ec.web.sendJsonResponse([success:false, error:'Choose a product from this organization.']); return
                }
                if (op.newPrice == null || !op.newPrice.toString().trim()) {
                    def configuredPrice = (prod.mrpAmount ?: 0) as BigDecimal
                    if (configuredPrice <= 0) {
                        def priceRow = ec.entity.find('mantle.product.ProductPrice').condition('productId',prod.productId)
                            .condition('priceTypeEnumId','PptList').orderBy('-lastUpdatedStamp').one()
                        if (!priceRow) priceRow = ec.entity.find('mantle.product.ProductPrice').condition('productId',prod.productId)
                            .condition('priceTypeEnumId','PptCurrent').orderBy('-lastUpdatedStamp').one()
                        configuredPrice = (priceRow?.price ?: 0) as BigDecimal
                    }
                    if (configuredPrice <= 0) { ec.web.sendJsonResponse([success:false,error:'Set a product price above ₹0 before adding it to an issued bill.']); return }
                }
                addedCount++
            } else if (!originalSeqs.contains(op.seq) || removedSeqs.contains(op.seq)) {
                ec.web.sendJsonResponse([success:false, error:'An edited item is missing or was already removed. Reload the bill.']); return
            }
            if (type == 'ITEM_REMOVED') removedSeqs.add(op.seq)
            if (type in ['QTY_CHANGE','PRICE_CHANGE','ITEM_ADDED']) {
                def raw = type == 'QTY_CHANGE' ? op.newQty : type == 'PRICE_CHANGE' ? op.newPrice : (op.addQty != null ? op.addQty : '1')
                def amount
                try { amount = new BigDecimal(raw.toString()) }
                catch (Exception ignored) { ec.web.sendJsonResponse([success:false, error:'Enter a valid quantity or price.']); return }
                if ((type == 'PRICE_CHANGE' && (amount <= 0 || amount.scale() > 2)) ||
                    (type != 'PRICE_CHANGE' && (amount <= 0 || amount.scale() > 3))) {
                    ec.web.sendJsonResponse([success:false, error:'Use a positive quantity (up to 3 decimals) or a price above ₹0 (up to 2 decimals).']); return
                }
                if (type == 'ITEM_ADDED' && op.newPrice != null && op.newPrice.toString().trim()) {
                    def addPrice
                    try { addPrice = new BigDecimal(op.newPrice.toString()) }
                    catch (Exception ignored) { ec.web.sendJsonResponse([success:false, error:'Enter a valid new-item price.']); return }
                    if (addPrice <= 0 || addPrice.scale() > 2) { ec.web.sendJsonResponse([success:false, error:'New-item price must be above ₹0 with up to 2 decimals.']); return }
                }
            }
        }
        if (originalItems.size() - removedSeqs.size() + addedCount < 1) {
            ec.web.sendJsonResponse([success:false, error:'An issued bill must retain at least one item. Void it instead.']); return
        }
        for (def editOp : editOps) {
        def editType = editOp.type
        def itemSeqId = editOp.seq
        def editedValue = editType == 'QTY_CHANGE' ? new BigDecimal(editOp.newQty.toString()) :
            editType == 'PRICE_CHANGE' ? new BigDecimal(editOp.newPrice.toString()) :
            editType == 'ITEM_ADDED' ? new BigDecimal((editOp.addQty != null ? editOp.addQty : '1').toString()) : null
        def currentTxn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId', txId).one()
        def oldGrand = (currentTxn.grandTotal ?: 0) as BigDecimal
        def invAdjProduct = null; def invAdjQty = BigDecimal.ZERO
        def _addedSeqId = null
        if (editType == 'QTY_CHANGE') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def oldQty = item.quantity as BigDecimal
            def newQty = editedValue
            invAdjProduct = item.productId; invAdjQty = oldQty - newQty
            def up = (item.unitPrice ?: 0) as BigDecimal
            def dp = (item.discountPercent ?: 0) as BigDecimal
            def ls = newQty * up
            def da = ls * dp / 100
            def originalNet=((item.quantity ?: 0) as BigDecimal)*((item.unitPrice ?: 0) as BigDecimal)-((item.discountAmount ?: 0) as BigDecimal)
            def taxableFraction=originalNet>0 ? ((item.taxableAmount ?: 0) as BigDecimal)/originalNet : BigDecimal.ONE
            def ta = (ls - da) * taxableFraction
            def taxR = BigDecimal.ZERO
            if (item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {
                taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)
            }
            def tt = ta * taxR
            def lt = ta + tt
            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId,
                    quantity:newQty, discountAmount:da, taxableAmount:ta,
                    totalTaxAmount:tt, lineTotal:lt]).call()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'QTY_CHANGE', itemSeqId:itemSeqId,
                    productId:item.productId, productName:item.productName ?: item.productId,
                    oldValue:'Qty: '+oldQty, newValue:'Qty: '+newQty,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'PRICE_CHANGE') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def oldPrice = item.unitPrice as BigDecimal
            def newPrice = editedValue
            def q = (item.quantity ?: 1) as BigDecimal
            def ls = q * newPrice
            def dp = (item.discountPercent ?: 0) as BigDecimal
            def da = ls * dp / 100
            def originalNet=((item.quantity ?: 0) as BigDecimal)*((item.unitPrice ?: 0) as BigDecimal)-((item.discountAmount ?: 0) as BigDecimal)
            def taxableFraction=originalNet>0 ? ((item.taxableAmount ?: 0) as BigDecimal)/originalNet : BigDecimal.ONE
            def ta = (ls - da) * taxableFraction
            def taxR = BigDecimal.ZERO
            if (item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {
                taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)
            }
            def tt = ta * taxR
            def lt = ta + tt
            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId,
                    unitPrice:newPrice, discountAmount:da, taxableAmount:ta,
                    totalTaxAmount:tt, lineTotal:lt]).call()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'PRICE_CHANGE', itemSeqId:itemSeqId,
                    productId:item.productId, productName:item.productName ?: item.productId,
                    oldValue:'Price: '+oldPrice, newValue:'Price: '+newPrice,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'ITEM_REMOVED') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def removedName = item.productName ?: item.productId
            def removedQty = item.quantity
            invAdjProduct = item.productId; invAdjQty = (removedQty ?: 0) as BigDecimal
            ec.service.sync().name("delete#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId]).call()
            ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem')
                .condition('referenceId',txId).condition('referenceSeqId',itemSeqId).deleteAll()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'ITEM_REMOVED', itemSeqId:itemSeqId,
                    productId:item.productId, productName:removedName,
                    oldValue:removedName+' x'+removedQty, newValue:'REMOVED',
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'ITEM_ADDED') {
            def productId = editOp.productId
            def addQty = editedValue
            def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()
            if (!prod || prod.ownerPartyId != txn.organizationPartyId) throw new IllegalStateException('Product is not available for this organization.')
            def unitPrice = BigDecimal.ZERO
            if (prod.mrpAmount) unitPrice = prod.mrpAmount as BigDecimal
            if (unitPrice == BigDecimal.ZERO) {
                def pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptList").orderBy("-lastUpdatedStamp").limit(1).one()
                if (!pp) pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptCurrent").orderBy("-lastUpdatedStamp").limit(1).one()
                if (pp?.price) unitPrice = pp.price as BigDecimal
            }
            if (editOp.newPrice != null && editOp.newPrice.toString().trim()) unitPrice = new BigDecimal(editOp.newPrice.toString())
            if (unitPrice <= 0) { ec.message.addError('Set a product price above ₹0 before adding it to an issued bill.'); return }
            def newSeqId = String.format("%05d", ++nextItemSeq)
            _addedSeqId = newSeqId
            invAdjProduct = productId; invAdjQty = BigDecimal.ZERO - addQty
            def ls = addQty * unitPrice
            // Preserve the issued bill's tax state, including when earlier edits in
            // this batch removed every old line. Use the same tax service as checkout.
            def taxAmt = BigDecimal.ZERO
            def taxable = ls
            def taxedItem = null
            if (billHasTax) {
                def taxResult = ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([
                    organizationPartyId:txn.organizationPartyId,
                    items:[[productId:productId, productTaxCode:prod.productTaxCode,
                        taxCategoryId:prod.taxCategoryId, quantity:addQty, unitAmount:unitPrice,
                        discountAmount:BigDecimal.ZERO, isTaxInclusive:'N']],
                    originRegionGeoId:txn.originRegionGeoId,
                    destinationRegionGeoId:txn.destinationRegionGeoId,
                    transactionType:'SALE']).call()
                if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString ?: 'Cannot calculate tax for the added product.')
                taxedItem = taxResult?.taxedItems ? taxResult.taxedItems[0] : null
                taxable = (taxedItem?.taxableAmount != null ? taxedItem.taxableAmount : ls) as BigDecimal
                taxAmt = (taxedItem?.totalTaxAmount ?: 0) as BigDecimal
            }
            def lineTotal = taxable + taxAmt
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:newSeqId, productId:productId,
                    productName:prod.printName ?: prod.productName ?: productId, productTaxCode:prod.productTaxCode,
                    quantity:addQty, unitPrice:unitPrice, taxableAmount:taxable, totalTaxAmount:taxAmt,
                    lineTotal:lineTotal, discountPercent:0, discountAmount:0]).call()
            if (taxedItem?.taxBreakdowns) {
                ec.service.sync().name('zenith.tax.TaxServices.store#TaxLineDetails').parameters([
                    referenceType:'PosTransactionItem', referenceId:txId, referenceSeqId:newSeqId,
                    taxBreakdowns:taxedItem.taxBreakdowns]).call()
            }
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'ITEM_ADDED', itemSeqId:newSeqId,
                    productId:productId, productName:prod.productName ?: productId,
                    oldValue:'N/A', newValue:(prod.productName ?: productId)+' x'+addQty+' @'+unitPrice,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        }
        if (['QTY_CHANGE','PRICE_CHANGE'].contains(editType)) {
            def changedLine=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).condition('itemSeqId',itemSeqId).one()
            def details=ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem').condition('referenceId',txId).condition('referenceSeqId',itemSeqId).list()
            details.each { detail -> detail.taxableAmount=changedLine.taxableAmount;detail.taxAmount=((changedLine.taxableAmount ?: 0) as BigDecimal)*((detail.taxRate ?: 0) as BigDecimal)/100;detail.update() }
        }
        def txnFinal = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
        def itemsFinal = ec.entity.find("zenith.erp.pos.PosTransactionItem")
            .condition("transactionId", txId).orderBy("itemSeqId").list()
        // Keep the linked Sales invoice consistent with the amended bill so revenue/GST reports stay correct.
        // Rebuilt in-place (same transaction) because the amended items are not yet committed for a force-new sync.
        if (txnFinal?.linkedInvoiceId) {
            def _iid = txnFinal.linkedInvoiceId
            def _inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
            if (_inv) {
                _inv.statusId = "InvoiceInProcess"; _inv.update()
                ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","InvoiceItem").condition("referenceId",_iid).deleteAll()
                ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId",_iid).deleteAll()
                for (li in itemsFinal) {
                    def _ii = ec.service.sync().name("mantle.account.InvoiceServices.create#InvoiceItem").parameters([
                        invoiceId:_iid, itemTypeEnumId:"ItemProduct", productId:li.productId,
                        description:li.productName, quantity:li.quantity, amount:li.unitPrice]).call()
                    ec.service.sync().name("update#mantle.account.invoice.InvoiceItem").parameters([
                        invoiceId:_iid, invoiceItemSeqId:_ii.invoiceItemSeqId, productTaxCode:li.productTaxCode,
                        taxableAmount:li.taxableAmount, totalTaxAmount:li.totalTaxAmount, discountAmount:li.discountAmount]).call()
                    def _tlds = ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","PosTransactionItem")
                                  .condition("referenceId",txId).condition("referenceSeqId",li.itemSeqId).orderBy("sequenceNum").list()
                    if (_tlds) {
                        def _bds = _tlds.collect { [taxAuthorityId:it.taxAuthorityId, taxRateId:it.taxRateId, taxCategoryId:it.taxCategoryId,
                            taxName:it.taxName, taxRate:it.taxRate, taxableAmount:it.taxableAmount, taxAmount:it.taxAmount,
                            isIncludedInPrice:it.isIncludedInPrice, countryGeoId:it.countryGeoId, regionGeoId:it.regionGeoId] }
                        ec.service.sync().name("zenith.tax.TaxServices.store#TaxLineDetails").parameters([
                            referenceType:"InvoiceItem", referenceId:_iid, referenceSeqId:_ii.invoiceItemSeqId,
                            parentReferenceType:"Invoice", parentReferenceId:_iid, currencyUomId:"INR", taxBreakdowns:_bds]).call()
                    }
                }
                def _inv2 = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
                _inv2.invoiceTotal = txnFinal.grandTotal
                _inv2.unpaidTotal = ((txnFinal.grandTotal ?: 0) as BigDecimal) - ((_inv2.appliedPaymentsTotal ?: 0) as BigDecimal)
                _inv2.totalTaxableAmount = txnFinal.subtotal
                _inv2.totalTaxAmount = txnFinal.totalTaxAmount
                _inv2.roundOffAmount = txnFinal.roundOff
                _inv2.statusId = "InvoiceFinalized"
                _inv2.update()
            }
        }
        // Adjust stock by the edit delta (return to / take from stock) -- tracked products only
        if (invAdjProduct && invAdjQty != BigDecimal.ZERO) {
            def _pT = ec.entity.find("mantle.product.Product").condition("productId", invAdjProduct).one()
            if (_pT?.inventoryTracked == 'Y') {
                try {
                    ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand").parameters([
                        organizationPartyId: txnFinal.organizationPartyId, productId: invAdjProduct,
                        quantityDiff: invAdjQty, reason: ('Bill edit ' + (txnFinal.transactionNumber ?: txId))]).call()
                } catch (Throwable e) { throw new IllegalStateException('Bill-edit stock adjustment failed; no changes were saved.', e) }
            }
        }
        // Payment reconciliation: refund (paid > new total) or extra collection (new total > paid)
        def _paid = (txnFinal.paidAmount ?: 0) as BigDecimal
        def _pay = (txnFinal.payableAmount ?: 0) as BigDecimal
        def _refundDue = BigDecimal.ZERO; def _balanceDue = BigDecimal.ZERO
        if (_paid > _pay) { _refundDue = _paid - _pay } else if (_pay > _paid) { _balanceDue = _pay - _paid }
        ec.service.sync().name("update#zenith.erp.pos.PosTransaction").parameters([transactionId:txId, changeAmount:_refundDue]).call()
        def paymentsFinal = ec.entity.find("zenith.erp.pos.PosPayment")
            .condition("transactionId", txId).list()
        def amendsFinal = ec.entity.find("zenith.erp.pos.PosTransactionAmendment")
            .condition("transactionId", txId).orderBy("-amendmentDate").list()
        result = [success:true, action:'amendBill',
            bill:[txId:txId, billNo:txnFinal.transactionNumber ?: txId,
                grand:txnFinal.grandTotal ?: 0, payable:txnFinal.payableAmount ?: 0,
                refundDue:_refundDue, balanceDue:_balanceDue, newSeq:_addedSeqId,
                subtotal:txnFinal.subtotal ?: 0, tax:txnFinal.totalTaxAmount ?: 0,
                items:itemsFinal.collect { [seq:it.itemSeqId, pid:it.productId,
                    name:it.productName ?: it.productId, qty:it.quantity ?: 0,
                    price:it.unitPrice ?: 0, tax:it.totalTaxAmount ?: 0, total:it.lineTotal ?: 0] },
                payments:paymentsFinal.collect { [method:it.paymentMethod ?: '', amount:it.amount ?: 0] },
                amendments:amendsFinal.collect { [date:ec.l10n.format(it.amendmentDate, 'dd/MM hh:mm a'),
                    type:it.changeType ?: '', reason:it.reason ?: '',
                    product:it.productName ?: '', oldVal:it.oldValue ?: '', newVal:it.newValue ?: ''] }
            ]]
        if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString)
        }
        def freeState = ec.service.sync().name('zenith.pos.PosFreeItemServices.get#FreeItemApprovalState').parameters([transactionId:txId]).call()
        if (freeState?.required) {
            context.freeApprovalPreview = freeState
            if (!p.freeItemReason) throw new IllegalStateException('FREE_ITEM_APPROVAL_REQUIRED')
            ec.service.sync().name('zenith.pos.PosFreeItemServices.approve#FreeItems').parameters([
                transactionId:txId,reason:p.freeItemReason,managerPin:p.freeItemManagerPin,expectedFingerprint:p.freeItemFingerprint]).call()
            if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString)
        }
        ec.web.sendJsonResponse(result)
        return
    } else if (action == 'listHeld') {
        def heldList = ec.entity.find("zenith.erp.pos.PosHeldTransaction")
            .condition("sessionId", sessionId).condition("statusId", "PhHeld")
            .orderBy("-holdTime").list()
        def heldResult = []
        def heldTotal = 0 as BigDecimal
        heldList.each { ht ->
            def itemsList = []
            def htTotal = (ht.subtotal ?: 0) as BigDecimal
            heldTotal += htTotal
            if (ht.itemsJson) {
                try {
                    def parsed = new groovy.json.JsonSlurper().parseText(ht.itemsJson)
                    if (parsed instanceof List) {
                        parsed.each { pi ->
                            itemsList.add([name: pi.productName ?: pi.productId ?: '', qty: pi.quantity ?: 0])
                        }
                    }
                } catch (Exception ignored) {}
            }
            def custName = ''
            if (ht.customerPartyId) {
                def cp = ec.entity.find("mantle.party.Person").condition("partyId", ht.customerPartyId).one()
                if (cp) custName = [(cp.firstName ?: ''), (cp.lastName ?: '')].findAll{it}.join(' ')
            }
            heldResult.add([heldId: ht.heldId, subtotal: htTotal,
                holdTime: ec.l10n.format(ht.holdTime, 'hh:mm a'),
                reason: ht.holdReason ?: '', customer: custName ?: 'Walk-In',
                itemCount: itemsList.size(), items: itemsList])
        }
        result = [success:true, action:'listHeld', held:heldResult, heldCount:heldList.size(), heldTotal:heldTotal]
        ec.web.sendJsonResponse(result)
        return
    } else if (action == 'sessionSummary') {



        def sess = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one()



        if (!sess || sess.statusId != 'PsOpen') {



            result = [success:false, error:'Session is not open']



            ec.web.sendJsonResponse(result)



            return



        }



        def txns = ec.entity.find("zenith.erp.pos.PosTransaction")



            .condition("sessionId", sessionId).condition("statusId", "PtCompleted").list()



        def txnIds = txns*.transactionId



        def totalSales = 0 as BigDecimal



        def cashReceived = 0 as BigDecimal



        def cardReceived = 0 as BigDecimal



        def upiReceived = 0 as BigDecimal



        def changeGiven = 0 as BigDecimal



        txns.each { totalSales += (it.grandTotal ?: 0) as BigDecimal; changeGiven += (it.changeAmount ?: 0) as BigDecimal }



        if (txnIds) {



            def payments = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", "in", txnIds).list()



            payments.each {



                def amt = (it.amount ?: 0) as BigDecimal



                if (it.paymentMethod == 'Cash') cashReceived += amt



                else if (it.paymentMethod == 'Card') cardReceived += amt



                else if (it.paymentMethod == 'UPI') upiReceived += amt



            }



        }



        def openingCash = (sess.openingCash ?: 0) as BigDecimal



        def drawer = ec.service.sync().name("zenith.pos.PosServices.get#PosSessionCashSummary").parameter("sessionId",sess.sessionId).call()
        def expectedCash = drawer.expectedCash



        result = [success:true, action:'sessionSummary',



            billCount:txns.size(), totalSales:totalSales,



            openingCash:openingCash, cashReceived:drawer.cashReceived,



            cardReceived:cardReceived, upiReceived:upiReceived,



            changeGiven:drawer.changeGiven, expectedCash:expectedCash]



        ec.web.sendJsonResponse(result)



        return



    }



    def txn = transactionId ? ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", transactionId).one() : null



    def items = transactionId ? ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", transactionId).orderBy("itemSeqId").list() : []



    def totalQty = 0; items.each { totalQty += (it.quantity ?: 0) }

    def modeSession = (txn?.sessionId ?: sessionId) ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',txn?.sessionId ?: sessionId).one() : null
    def offeredModes = modeSession ? ec.service.sync().name('zenith.pos.PosModeServices.get#TerminalModes').parameter('terminalId',modeSession.terminalId).call().modes : []



    result = [success:true, transactionId:transactionId ?: '', txnNum:txn?.transactionNumber ?: '',



        items: items.collect { [seq:it.itemSeqId, pid:it.productId, name:it.productName ?: it.productId,



            qty:it.quantity ?: 0, price:it.unitPrice ?: 0, total:it.lineTotal ?: 0,



            tax:it.totalTaxAmount ?: 0, disc:it.discountPercent ?: 0, mode:(it.salesModeId ?: ''), uom:(it.uomId ? (["OTH_ea":'Nos',"WT_g":'g',"WT_kg":'kg',"VLIQ_ml":'ml',"VLIQ_L":'L',"LEN_m":'m',"LEN_cm":'cm'].get(it.uomId) ?: '') : '')] },



        sub:txn?.subtotal ?: 0, tax:txn?.totalTaxAmount ?: 0, disc:txn?.discountTotal ?: 0,



        grand:txn?.grandTotal ?: 0, pay:txn?.payableAmount ?: 0, paid:txn?.paidAmount ?: 0, round:txn?.roundOff ?: 0,
        customer:txn?.customerName ?: '', customerPhone:txn?.customerPhone ?: '', customerPartyId:txn?.customerPartyId ?: '',
        customerCreditDays:txn?.customerPartyId ? ec.entity.find('mantle.party.Party').condition('partyId',txn.customerPartyId).one()?.creditDays : null,
        creditDateToday:ec.l10n.format(ec.user.nowTimestamp,'yyyy-MM-dd'), creditTimeZone:ec.user.timeZone.ID,



        cnt:items.size(), tQty:totalQty, modes:offeredModes.collect{[id:it.salesModeId, name:it.modeName, disc:(it.discountPercent ?: 0)]}]



} catch (Exception e) {



    if (action == 'applyDiscount') {
        ec.transaction.setRollbackOnly('POS bill discount failed', e)
        if (ec.message.hasError()) ec.message.clearErrors()
    }
    if (action == 'amendBill') {
        ec.transaction.setRollbackOnly('POS bill amendment failed', e)
        if (ec.message.hasError()) ec.message.clearErrors()
    }
    result = [success:false, needFreeApproval:e.message?.contains('FREE_ITEM_APPROVAL_REQUIRED'),
        freeItems:context.freeApprovalPreview?.freeItems,approvalFingerprint:context.freeApprovalPreview?.approvalFingerprint,error:e.message]



}



ec.web.sendJsonResponse(result)

else.script:
ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

actions.script:
gridProducts=[]; gridCardStock=[:]; gridHasMore=false; gridNextOffset=0; gridOffset=0
if (sessionId) {
    def page=ec.service.sync().name('zenith.pos.PosCheckoutServices.get#PosCatalogPage')
        .parameters([sessionId:sessionId,searchTerm:searchTerm,catId:catId,productOffset:productOffset]).call()
    gridProducts=page.gridProducts ?: []; gridCardStock=page.gridCardStock ?: [:]
    gridHasMore=page.gridHasMore ?: false; gridNextOffset=page.gridNextOffset ?: 0
    gridOffset=page.gridOffset ?: 0
}
lastBillNo = '-'
lastBillAmt = '0'
if (sessionId) {
    // A recalled older cart may finish after a newer cart. Use completion
    // time, retaining a creation-time fallback only for undated legacy bills.
    def lastBill = ec.entity.find('zenith.erp.pos.PosTransaction')
        .condition('organizationPartyId', posOrg ?: '__NO_ORGANIZATION__')
        .condition('sessionId', sessionId).condition('statusId', 'PtCompleted')
        .condition('completedDate', org.moqui.entity.EntityCondition.NOT_EQUAL, null)
        .useCache(false).orderBy('-completedDate,-lastUpdatedStamp').limit(1).list()[0]
    if (!lastBill) lastBill = ec.entity.find('zenith.erp.pos.PosTransaction')
        .condition('organizationPartyId', posOrg ?: '__NO_ORGANIZATION__')
        .condition('sessionId', sessionId).condition('statusId', 'PtCompleted')
        .useCache(false).orderBy('-entryDate,-lastUpdatedStamp').limit(1).list()[0]
    if (lastBill) {
        lastBillNo = lastBill.transactionNumber ?: lastBill.transactionId
        lastBillAmt = zinr.inr(ec.l10n.format(lastBill.payableAmount ?: 0, '#,##0.00'))
    }
}
// Count completed bills by completion time, including legacy FY-numbered bills issued
// earlier on the migration day. India business time is shared by every cashier.
def _billDay = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone('Asia/Kolkata'))
_billDay.setTime(ec.user.nowTimestamp)
def _billDayFmt = new java.text.SimpleDateFormat('yyyyMMdd')
_billDayFmt.setTimeZone(java.util.TimeZone.getTimeZone('Asia/Kolkata'))
billDayKey = _billDayFmt.format(ec.user.nowTimestamp)
_billDay.set(java.util.Calendar.HOUR_OF_DAY, 0)
_billDay.set(java.util.Calendar.MINUTE, 0)
_billDay.set(java.util.Calendar.SECOND, 0)
_billDay.set(java.util.Calendar.MILLISECOND, 0)
def _billStart = new java.sql.Timestamp(_billDay.getTimeInMillis())
_billDay.add(java.util.Calendar.DATE, 1)
def _billEnd = new java.sql.Timestamp(_billDay.getTimeInMillis())
def _billDayQuery = ec.entity.find('zenith.erp.pos.PosTransaction')
    .condition('organizationPartyId', posOrg).condition('statusId', 'PtCompleted')
    .condition('completedDate', org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _billStart)
    .condition('completedDate', org.moqui.entity.EntityCondition.LESS_THAN, _billEnd)
todayBillCount = _billDayQuery.count()
latestIssuedBillNo = ec.entity.find('zenith.erp.pos.PosTransaction')
    .condition('organizationPartyId', posOrg).condition('statusId', 'PtCompleted')
    .condition('completedDate', org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _billStart)
    .condition('completedDate', org.moqui.entity.EntityCondition.LESS_THAN, _billEnd)
    .useCache(false).orderBy('-completedDate,-lastUpdatedStamp').limit(1).list()[0]?.transactionNumber ?: ''







cartQty = BigDecimal.ZERO



if (cartItems) {



    cartQty = cartItems.sum { (it.quantity ?: 0) as BigDecimal } ?: BigDecimal.ZERO



}



cartAmt = txn?.payableAmount ?: BigDecimal.ZERO



cartDisc = txn?.discountTotal ?: BigDecimal.ZERO







heldTxns = []



if (sessionId) {



    heldTxns = ec.entity.find("zenith.erp.pos.PosHeldTransaction")



        .condition("sessionId", sessionId).condition("statusId", "PhHeld")



        .orderBy("holdTime").list()



}

// Enriched held-bill list for the server-rendered picker (works in /qapps without JS).
heldList = []
def _hi = 0
for (ht in (heldTxns ?: [])) {
    _hi++
    def cnt = 0
    try { cnt = new groovy.json.JsonSlurper().parseText(ht.itemsJson ?: '[]').size() } catch (Exception e) { cnt = 0 }
    heldList.add([ heldId: ht.heldId, num: _hi, subtotal: (ht.subtotal ?: 0),
                   itemCount: cnt, timeStr: ec.l10n.format(ht.holdTime, 'hh:mm a'),
                   reason: (ht.holdReason ?: '') ])
}





dispDate = ec.l10n.format(ec.user.nowTimestamp, 'dd-MM-yyyy')



dispTime = ec.l10n.format(ec.user.nowTimestamp, 'hh:mm:ss a')







salesMode = 'RETAIL'



salesModeColor = '#2e7d32'



salesModesList = []



try {



    def allModes = terminal?.terminalId ? ec.service.sync().name('zenith.pos.PosModeServices.get#TerminalModes').parameter('terminalId',terminal.terminalId).call().modes : []



    salesModesList = allModes



    def currentMode = null



    if (salesModeId) {



        currentMode = allModes.find { it.salesModeId == salesModeId }



    }



    if (!currentMode) {



        currentMode = allModes.find { it.isDefault == 'Y' }



    }



    if (!currentMode && allModes) {



        currentMode = allModes[0]



    }



    if (currentMode) {



        salesMode = currentMode.modeName ?: 'RETAIL'



        salesModeId = currentMode.salesModeId



        salesModeColor = currentMode.colorCode ?: '#2e7d32'
        if (transactionId) {
            def _txm = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", transactionId).one()
            if (_txm != null && _txm.salesModeId != currentMode.salesModeId) {
                ec.service.sync().name("zenith.pos.PosServices.reprice#PosTransaction").parameters([transactionId:transactionId, discountPercent:(currentMode.discountPercent ?: 0), salesModeId:currentMode.salesModeId, taxOn:taxOn]).call()
                if (ec.message.hasError()) {
                    // A cart line has no price in the requested mode -> keep the current mode and tell the cashier.
                    modeSwitchError = ec.message.errorsString; ec.message.clearErrors()
                    def _prev = allModes.find { it.salesModeId == _txm.salesModeId }
                    if (_prev) { currentMode = _prev; salesMode = _prev.modeName ?: 'RETAIL'; salesModeId = _prev.salesModeId; salesModeColor = _prev.colorCode ?: '#2e7d32' }
                } else {
                    ec.service.sync().name("update#zenith.erp.pos.PosTransaction").parameters([transactionId:transactionId, salesModeId:currentMode.salesModeId]).call()
                }
            }
        }



    }



    // Per-mode grid pricing: the active mode's price per card + a blocked flag
    // for products with no price in a fixed-price mode (so the card can be disabled).
    gridModePrice = [:]; gridModeBlocked = [:]
    def _fx = currentMode != null && currentMode.priceSource == 'PpsFixedProduct'
    if (gridProducts) {
        if (_fx) {
            def _gids = gridProducts.collect { it.productId }
            def _pmap = [:]
            if (_gids) ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("salesModeId", currentMode.salesModeId).condition("productId", "in", _gids).list().each { _pmap[it.productId] = it.price }
            gridProducts.each { gp -> def _pp = _pmap[gp.productId]; gridModePrice[gp.productId] = _pp; gridModeBlocked[gp.productId] = (_pp == null) }
        } else {
            gridProducts.each { gp -> gridModePrice[gp.productId] = gp.mrpAmount; gridModeBlocked[gp.productId] = false }
        }
    }
} catch (Exception e) { /* PosSalesMode may not exist yet */ }

// ZE-POS-0201: mirror the ZenithApp posOnly role gate so the header can HIDE the back-office
// affordances a POS-only cashier can't reach — Inventory (ITEM/CATALOGUE) and the Dashboard/App
// links all bounce straight back here. Sole Zenith role ZENITH_CASHIER, and not the super-admin.
posOnlyUser = false
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        posOnlyUser = (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER"))
    }
} catch (Exception e) { posOnlyUser = false }

busySessionLinks = []
(terminalList ?: []).findAll { _blockedTerms.contains(it.terminalId) }.each { term ->
    def matching = ec.entity.find('zenith.erp.pos.PosSession')
        .condition('organizationPartyId', posOrg ?: '__NO_ORGANIZATION__')
        .condition('terminalId', term.terminalId).condition('statusId', 'PsOpen').list()
        .find { s -> ec.entity.find('zenith.erp.pos.PosTransaction')
            .condition('sessionId', s.sessionId).condition('statusId', 'PtCompleted').count() > 0 }
    if (matching) busySessionLinks.add([terminalName:term.terminalName ?: term.terminalId,
        sessionId:matching.sessionId])
}

def checkoutNames=(terminalList ?: []).collectEntries { [(it.terminalId):it.terminalName] }
checkoutCounters=sessionId ? ec.entity.find('zenith.erp.pos.PosSession')
    .condition('organizationPartyId',posOrganizationPartyId).condition('operatorPartyId',ec.user.userAccount?.partyId)
    .condition('statusId','PsOpen').orderBy('-openDate').limit(100).list().collect { s ->
        [sessionId:s.sessionId,name:checkoutNames[s.terminalId] ?: s.terminalId]
    } : []
